    public decimal CalculateAverageMonthlyCost(List<decimal> monthlyGroceryCosts)
    {
        // implementation here
    }
}
```

Now, let's create a test class called `GroceryCalculatorTests` to test this method:

```csharp
using Xunit;
using System.Collections.Generic;

public class GroceryCalculatorTests
{
    private readonly GroceryCalculator _calculator;

    public GroceryCalculatorTests()
    {
        _calculator = new GroceryCalculator();
    }

    [Fact]
    public void CalculateAverageMonthlyCost_WithValidInput_ReturnsCorrectAverage()
    {
        // Arrange
        var monthlyGroceryCosts = new List<decimal> { 100, 150, 200, 120, 180, 160, 140, 130, 110, 170, 190, 210 };

        // Act
        var result = _calculator.CalculateAverageMonthlyCost(monthlyGroceryCosts);

        // Assert
        Assert.Equal(150, result);
    }

    [Fact]
    public void CalculateAverageMonthlyCost_WithEmptyInput_ReturnsZero()
    {
        // Arrange
        var monthlyGroceryCosts = new List<decimal>();

        // Act
        var result = _calculator.CalculateAverageMonthlyCost(monthlyGroceryCosts);

        // Assert
        Assert.Equal(0, result);
    }

    [Fact]
    public void CalculateAverageMonthlyCost_WithNullInput_ThrowsArgumentNullException()
    {
        // Arrange
        List<decimal> monthlyGroceryCosts = null;

        // Act & Assert
        Assert.Throws<ArgumentNullException>(() => _calculator.CalculateAverageMonthlyCost(monthlyGroceryCosts));
    }
}
```

These tests cover the following scenarios:

1. A valid input with 12 monthly grocery costs, ensuring the average is calculated correctly.
2. An empty input, ensuring the method returns zero.
3. A null input, ensuring the method throws an `ArgumentNullException`.

You can add more tests to cover other edge cases or scenarios as needed.
