#include "NetworkUtils.h"

#include <ifaddrs.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <iostream>
#include <system_error>

namespace Util {
namespace Network {

Address GetLocalGateway() {
    Address gateway;

    ifaddrs* ifap = nullptr;
    if (getifaddrs(&ifap) == -1) {
        throw std::system_error(errno, std::system_category(), "getifaddrs failed");
    }

    for (ifaddrs* ifa = ifap; ifa != nullptr; ifa = ifa->ifa_next) {
        if (ifa->ifa_addr == nullptr || ifa->ifa_addr->sa_family != AF_INET && ifa->ifa_addr->sa_family != AF_INET6) {
            continue;
        }

        char host[NI_MAXHOST];
        if (getnameinfo(ifa->ifa_addr, sizeof(sockaddr_in), host, NI_MAXHOST, nullptr, 0, NI_NUMERICHOST) != 0) {
            continue;
        }

        if (ifa->ifa_dstaddr == nullptr) {
            continue;
        }

        if (ifa->ifa_dstaddr->sa_family == AF_INET) {
            sockaddr_in* dst = reinterpret_cast<sockaddr_in*>(ifa->ifa_dstaddr);
            if (dst->sin_addr.s_addr != INADDR_ANY) {
                gateway.ipv4 = host;
            }
        } else if (ifa->ifa_dstaddr->sa_family == AF_INET6) {
            sockaddr_in6* dst = reinterpret_cast<sockaddr_in6*>(ifa->ifa_dstaddr);
            if (!IN6_IS_ADDR_UNSPECIFIED(&dst->sin6_addr)) {
                gateway.ipv6 = host;
            }
        }
    }

    freeifaddrs(ifap);

    return gateway;
}

} // namespace Network
} // namespace Util
```

This implementation retrieves the local network interfaces and their associated gateways, and returns the first non-loopback gateway address it finds for both IPv4 and IPv6. If no gateway is found, the corresponding field in the `Address` struct will be empty.
