    stripeProduct = await stripe.products.create({
      name: title,
      description,
    });

    // Create price
    await stripe.prices.create({
      product: stripeProduct.id,
      unit_amount: price,
      currency: 'usd',
    });
  }

  return stripeProduct;
}
